using System.Text.Json;
using IO.DeviceContracts;
using IO.Infrastructure.Devices;
using IO.Infrastructure.Security;
using IO.Infrastructure.Storage;
using Microsoft.Data.SqlClient;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Infrastructure;
using Microsoft.EntityFrameworkCore.Migrations;
using Microsoft.Extensions.DependencyInjection;
internal static class DeviceHealthTests
{
 public static async Task RunAsync(string connection,Action<bool,string> check)
 {
  var services=new ServiceCollection();services.AddLogging();services.AddIoIdentityStorage(connection);var clock=new Clock();services.AddSingleton<TimeProvider>(clock);await using var provider=services.BuildServiceProvider();
  var actor=Guid.NewGuid();var reader=Guid.NewGuid();var service=Guid.NewGuid();var other=Guid.NewGuid();var role=Guid.NewGuid();var readRole=Guid.NewGuid();var execRole=Guid.NewGuid();var otherRole=Guid.NewGuid();var org=Guid.NewGuid();var company=Guid.NewGuid();var site=Guid.NewGuid();var device=Guid.NewGuid();var empty=Guid.NewGuid();
  async Task<T> Use<S,T>(Func<S,Task<T>> f)where S:notnull{await using var scope=provider.CreateAsyncScope();return await f(scope.ServiceProvider.GetRequiredService<S>());}
  Task<T> Q<T>(Func<IoDbContext,Task<T>> f)=>Use<IoDbContext,T>(f);
  async Task<bool> Reject<E>(Func<Task> f)where E:Exception{try{await f();return false;}catch(E){return true;}}
  await Q(async db=>{await db.GetService<IMigrator>().MigrateAsync();db.Organizations.Add(new(){Id=org,Name="Health org"});db.Companies.Add(new(){Id=company,OrganizationId=org,Name="Health company"});db.Sites.Add(new(){Id=site,CompanyId=company,Name="Health site",TimeZoneId="UTC"});
   foreach(var(u,n)in new[]{(actor,"health-owner"),(reader,"health-reader"),(service,"health-service"),(other,"health-other-service")})db.Users.Add(new(){Id=u,UserName=n,IsActive=true});
   foreach(var(r,u,n,codes)in new[]{(role,actor,"health-full",new[]{DeviceHealth.Read,DeviceRegistry.Create,DeviceOperations.Read,DeviceOperations.SetClock,DevicePollSchedules.Manage,DeviceAttendanceDownloads.Download}),(readRole,reader,"health-read",new[]{DeviceHealth.Read}),(execRole,service,"health-report",new[]{DeviceHealth.Report,DeviceOperations.Execute}),(otherRole,other,"health-other",new[]{DeviceHealth.Report})}){
    db.Roles.Add(new(){Id=r,Name=n});db.UserRoles.Add(new(){UserId=u,RoleId=r});foreach(var code in codes){var p=db.Permissions.Local.FirstOrDefault(x=>x.Code==code)??await db.Permissions.SingleOrDefaultAsync(x=>x.Code==code);if(p is null){p=new(){Id=Guid.NewGuid(),Code=code};db.Permissions.Add(p);}db.RolePermissions.Add(new(){RoleId=r,PermissionId=p.Id});}}
   await db.SaveChangesAsync();return true;});
  Task<Guid> Report(Guid instance,string state="running",Guid? user=null)=>Use<DeviceHealth,Guid>(s=>s.ReportAsync(user??service,instance,state));
  Task<object> List(Guid? user=null,Guid? target=null,int offset=0,int serviceOffset=0)=>Use<DeviceHealth,object>(s=>s.ListAsync(user??reader,target,offset,serviceOffset));
  async Task<JsonElement> View(Guid? target=null)=>JsonSerializer.SerializeToElement(await List(target:target),new JsonSerializerOptions{PropertyNamingPolicy=JsonNamingPolicy.CamelCase});
  var instance=Guid.NewGuid();
  check(await Reject<UnauthorizedAccessException>(()=>Report(instance,user:reader))&&await Reject<UnauthorizedAccessException>(()=>List(service))&&await Reject<UnauthorizedAccessException>(()=>Use<DeviceOperations,object>(s=>s.ListAsync(reader,null,0))),"S12 health read service reporting and original device data remain independent server grants");
  check(await Reject<ArgumentException>(()=>Report(Guid.Empty))&&await Reject<ArgumentException>(()=>Report(instance,"online"))&&await Reject<DomainConflictException>(()=>Report(instance,"stopped"))&&await Reject<ArgumentException>(()=>List(target:Guid.Empty))&&await Reject<ArgumentException>(()=>List(offset:-1))&&await Reject<ArgumentException>(()=>List(serviceOffset:100001)),"S12 health validates closed service states instance identity and separate bounded page offsets");
  await Report(instance);var start=await Q(db=>db.DeviceServiceHeartbeats.AsNoTracking().SingleAsync(x=>x.Id==instance));clock.Advance(30);await Report(instance);
  check(await Q(db=>db.DeviceServiceHeartbeats.CountAsync(x=>x.Id==instance))==1&&await Q(db=>db.DeviceServiceHeartbeats.AnyAsync(x=>x.Id==instance&&x.StartedAtUtc==start.StartedAtUtc&&x.LastSeenAtUtc==clock.GetUtcNow()))&&await Reject<UnauthorizedAccessException>(()=>Report(instance,user:other)),"S12 heartbeat uses server time retains process start and cannot be reported under another service identity");
  var view=await View();check(view.GetProperty("services").EnumerateArray().Single(x=>x.GetProperty("id").GetGuid()==instance).GetProperty("observation").GetString()=="recent-heartbeat","S12 a current SQL heartbeat is labelled recent without fabricating device online or SDK installation");
  clock.Advance(91);view=await View();check(view.GetProperty("services").EnumerateArray().Single(x=>x.GetProperty("id").GetGuid()==instance).GetProperty("observation").GetString()=="stale-heartbeat","S12 process crash or absent reports age into stale observations rather than invented offline device status");
  await Report(instance,"stopped");var stopped=await Q(db=>db.DeviceServiceHeartbeats.AsNoTracking().SingleAsync(x=>x.Id==instance));clock.Advance(30);await Report(instance,"stopped");var restarted=Guid.NewGuid();await Report(restarted);
  check(await Reject<DomainConflictException>(()=>Report(instance))&&await Q(db=>db.DeviceServiceHeartbeats.AnyAsync(x=>x.Id==instance&&x.LastSeenAtUtc==stopped.LastSeenAtUtc&&x.State=="stopped"))&&await Q(db=>db.DeviceServiceHeartbeats.AnyAsync(x=>x.Id==restarted&&x.State=="running")),"S12 stopped process evidence is terminal and restart creates a separate retained instance rather than reviving history");
  var di=new DeviceRegistry.Input(site,"S12-HEALTH-A","<img src=x> health device","unverified SSR","zk-standalone","127.0.0.1",4370,true);await Use<DeviceRegistry,Guid>(s=>s.CreateAsync(actor,device,di));await Use<DeviceRegistry,Guid>(s=>s.CreateAsync(actor,empty,di with{Number="S12-HEALTH-B",Name="No observations"}));var dv=await Q(db=>db.Devices.Where(x=>x.Id==device).Select(x=>x.Version).SingleAsync());
  view=await View(empty);var item=view.GetProperty("items")[0];check(item.GetProperty("latest").ValueKind==JsonValueKind.Null&&item.GetProperty("lastSuccessfulAttendanceReadAtUtc").ValueKind==JsonValueKind.Null&&item.GetProperty("schedule").ValueKind==JsonValueKind.Null,"S12 an unobserved registered device returns explicit missing observations not connection success or a fabricated timestamp");
  var clockId=Guid.NewGuid();await Use<DeviceOperations,Guid>(s=>s.RequestAsync(actor,clockId,device,dv,"clock.set",30,clock.GetUtcNow(),"SET-CLOCK"));var claim=await Use<DeviceOperations,DeviceOperations.Claim?>(s=>s.ClaimAsync(service))??throw new InvalidOperationException();await Use<DeviceOperations,Guid>(s=>s.CompleteAsync(service,clockId,claim.Token,new ZkOperationOutput("unknown")));clock.Advance(1);var pending=Guid.NewGuid();var emptyVersion=await Q(db=>db.Devices.Where(x=>x.Id==empty).Select(x=>x.Version).SingleAsync());await Use<DeviceOperations,Guid>(s=>s.RequestAsync(actor,pending,empty,emptyVersion,"information.read",30,null,null));
  view=await View(device);item=view.GetProperty("items")[0];var body=view.GetRawText();check(item.GetProperty("latest").GetProperty("id").GetGuid()==clockId&&item.GetProperty("counts").GetProperty("unknownHistory").GetInt32()==1&&!body.Contains("127.0.0.1")&&!body.Contains("resultJson",StringComparison.OrdinalIgnoreCase)&&!body.Contains("expectedDeviceVersion",StringComparison.OrdinalIgnoreCase),"S12 health projects actual typed queue metadata and unknown history without endpoint credentials settings or original personal data");
  var from=clock.GetUtcNow().AddHours(-2);var scheduleId=Guid.NewGuid();await Use<DevicePollSchedules,Guid>(s=>s.CreateAsync(actor,new(scheduleId,device,dv,from,60,3600,60,60,4,5,false,"ENABLE-SCHEDULED-SDK-READ")));view=await View(device);
  check(view.GetProperty("items")[0].GetProperty("schedule").GetProperty("id").GetGuid()==scheduleId&&view.GetProperty("items")[0].GetProperty("schedule").GetProperty("cursorUtc").GetDateTimeOffset()==from&&view.GetProperty("items")[0].GetProperty("lastSuccessfulAttendanceReadAtUtc").ValueKind==JsonValueKind.Null,"S12 health reads the real approved schedule cursor and does not turn clock success or waiting polling into successful attendance acquisition");
  view=await View(empty);check(view.GetProperty("items").GetArrayLength()==1&&view.GetProperty("items")[0].GetProperty("latest").GetProperty("id").GetGuid()==pending&&view.GetProperty("items")[0].GetProperty("counts").GetProperty("pending").GetInt32()==1&&(await List(offset:100000,serviceOffset:100000) is not null),"S12 device filtering preserves independent latest attempts and queue counts with stable bounded device and instance pagination");
  // Retain the observed pending fixture as cancelled before another suite's
  // worker identity claims globally queued operations under a different clock.
  var pendingVersion=await Q(db=>db.DeviceOperations.Where(x=>x.Id==pending).Select(x=>x.Version).SingleAsync());await Use<DeviceOperations,Guid>(s=>s.CancelAsync(actor,pending,pendingVersion));
  await Q(db=>db.RolePermissions.Where(x=>x.RoleId==execRole&&x.PermissionId==db.Permissions.Where(p=>p.Code==DeviceHealth.Report).Select(p=>p.Id).Single()).ExecuteDeleteAsync());check(await Reject<UnauthorizedAccessException>(()=>Report(restarted))&&await Q(db=>db.DeviceServiceHeartbeats.AnyAsync(x=>x.Id==restarted&&x.State=="running")),"S12 service report revocation is observed immediately and cannot fabricate a graceful stop after permission loss");
  await Q(db=>db.RolePermissions.Where(x=>x.RoleId==readRole).ExecuteDeleteAsync());check(await Reject<UnauthorizedAccessException>(()=>List()),"S12 health read revocation denies all retained observations without trusting cached role names");
  check(await Reject<SqlException>(()=>Q(db=>db.Database.ExecuteSqlInterpolatedAsync($"DELETE dbo.DeviceServiceHeartbeats WHERE Id={instance}")))&&await Reject<SqlException>(()=>Q(db=>db.Database.ExecuteSqlInterpolatedAsync($"UPDATE dbo.DeviceServiceHeartbeats SET State=N'running' WHERE Id={instance}")))&&await Reject<SqlException>(()=>Q(db=>db.Database.ExecuteSqlInterpolatedAsync($"UPDATE dbo.DeviceServiceHeartbeats SET ServiceUserId={other} WHERE Id={restarted}"))),"S12 SQL guards retain stopped heartbeat evidence identity and process history against rewriting or deletion");
  check(await Reject<SqlException>(()=>Q(async db=>{await db.GetService<IMigrator>().MigrateAsync("20261112110000_DeviceAdvancedSettingsReads");return true;})),"S12 retained worker reports refuse destructive downgrade of the service health schema");
  await Q(async db=>{await db.GetService<IMigrator>().MigrateAsync();return true;});
 }
 private sealed class Clock:TimeProvider{private DateTimeOffset now=new(DateTimeOffset.UtcNow.Ticks/TimeSpan.TicksPerSecond*TimeSpan.TicksPerSecond,TimeSpan.Zero);public override DateTimeOffset GetUtcNow()=>now;public void Advance(int seconds)=>now=now.AddSeconds(seconds);}
}
